fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    assert_eq!(s1.len(), s2.len(), "All input arrays must have equal length");
    assert_eq!(s1.len(), s3.len(), "All input arrays must have equal length");

    let n = s1.len();

    // Assumption states 3n fits in i32; for Rust allocation we ensure it fits in usize too.
    let cap = n
        .checked_mul(3)
        .expect("Length overflow when computing 3n");

    let mut res = Vec::with_capacity(cap);
    for i in 0..n {
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
    }
    res
}